def frequency_Of_Largest(n, arr):
    """Write a python function to find the frequency of the largest value in a given array."""
    if arr is None:
        return 0
    values = list(arr)
    if n is not None:
        try:
            limit = int(n)
        except (TypeError, ValueError):
            limit = len(values)
        if limit <= 0:
            return 0
        values = values[:limit]
    if not values:
        return 0
    largest = max(values)
    return values.count(largest)
